mapper.select:
SELECT user_id AS userId, MIN(create_date) AS firstLoginDate, MAX(create_date) AS lastLoginDate, COUNT(*) AS loginCount FROM tb_user_login_log WHERE user_id IN
#{uid}
AND opera_type = 0 AND opera_status = 0 AND is_deleted = 0
AND create_date >= #{startDate}
AND create_date < #{endDate}
GROUP BY user_id
